steps.script:
function transform(ctx) {
  var u = ctx.vars.portal_url || "";
  if (!u || u.indexOf("?") < 0) throw new Error("未能从官网页面提取认证跳转地址，请核对门户地址");
  // 原实现 get_query_string_requests.py L27：先替换为 %26/%3D，requests data= 提交时把 % 再编码为 %25 => 线上等效 %2526/%253D
  var qs = u.slice(u.indexOf("?") + 1).replace(/&/g, "%2526").replace(/=/g, "%253D");
  // shmtu_auth_const_value.py ServiceType.EDU 为预编码串 "%E6%A0%A1%E5%9B%AD%E7%BD%91"，requests 提交时再编码一次 => 双重编码
  return { eu: url_encode(ctx.username || ""), ep: url_encode(ctx.password || ""), es: url_encode("%E6%A0%A1%E5%9B%AD%E7%BD%91"), qse: qs };
}
